def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v != 0]
    if not cells:
        return [row[:] for row in grid]
    bottom = max(r for r, _ in cells)
    out = [[0] * w for _ in range(h)]
    for r, c in cells:
        nc = c + r - bottom
        if 0 <= nc < w:
            out[r][nc] = grid[r][c]
    return out
